import type { AppEnvironment } from './readiness';
/** CloudflareBindings is generated by `pnpm types:worker`; APP_ENV varies between environments. */
export type HonoEnvironment = {
  Bindings: Omit<CloudflareBindings, 'APP_ENV'> & { APP_ENV: string };
  Variables: { request_id: string; environment: AppEnvironment };
};
export function isApiPath(pathname: string): boolean {
  return pathname === '/api' || pathname.startsWith('/api/');
}
